{ arg out=0, freq=440, amp=0.1, gate=1, rq=0.5, filterBaseFreq=2000;
    var sig, env;
    env = EnvGen.ar(
        Env.adsr(0.005, 0.1, 0.7, 0.5, curve: -4), 
        gate: gate,
        doneAction: 2
    );
    sig = Saw.ar(freq);
    sig = LPF.ar(sig, filterBaseFreq + (env * 2000), rq);
    sig = sig * amp * env;
    Out.ar(out, sig ! 2);
}
